<script setup lang="ts">
import {computed,nextTick,onUnmounted,ref,shallowRef,watch} from 'vue'
import {api,ApiError} from '../api/client'
import {session,can,contextGeneration,switchingTenant} from '../stores/session'
import type {EventMetricWindow} from '../utils/eventOperationalMetrics'
import {createNoiseTrendReader,createNoiseRecordsReader,emptyNoiseRead,noiseLayers,type NoiseTrend,type NoiseRecordPage,type NoiseRecordQuery,type NoiseBucket,type NoiseMarker} from '../utils/eventNoiseTrend'
import {displayTime} from '../utils/display'
import ApiErrorNotice from './ApiErrorNotice.vue'
const root=ref<HTMLElement>(),recordRegion=ref<HTMLElement>()
const props=defineProps<{window:EventMetricWindow}>(),trend=shallowRef(emptyNoiseRead<NoiseTrend,EventMetricWindow>()),records=shallowRef(emptyNoiseRead<NoiseRecordPage,NoiseRecordQuery>()),showTable=ref(false)
const trendReader=createNoiseTrendReader(api,s=>trend.value=s),recordReader=createNoiseRecordsReader(api,s=>records.value=s)
const permitted=computed(()=>session.value?.mode==='remote_test'&&['padmin','msp'].includes(session.value.user.role)&&can('dashboard:read')&&can('tickets:read')&&!switchingTenant.value)
let trendBlocked=false
const currentScope=()=>{const s=session.value;return s&&permitted.value?{tenantId:s.tenant.id,actorId:s.user.id,permissionVersion:s.permission_version,canRead:true}:null}
const authFailure=(error:unknown)=>error instanceof ApiError&&(error.status===401||error.status===403)
watch(()=>trend.value.error,error=>{if(authFailure(error))recordReader.reset(null)},{flush:'sync'})
watch(()=>records.value.error,error=>{if(authFailure(error)){trendBlocked=true;trendReader.reset(null)}},{flush:'sync'})
const scopeKey=computed(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.permission_version,session.value?.account_version,session.value?.user.role,session.value?.capabilities,permitted.value,props.window]))
watch(scopeKey,()=>{trendBlocked=false;const scope=currentScope();trendReader.reset(scope);recordReader.reset(scope);if(scope)void trendReader.load(props.window)},{immediate:true,flush:'sync'})
onUnmounted(()=>{trendReader.dispose();recordReader.dispose()})
function refresh(){if(permitted.value){if(trendBlocked){trendReader.reset(currentScope());trendBlocked=false}void trendReader.load(props.window)}}
async function cancelTrend(){if(!trend.value.busy)return;const owner=scopeKey.value,active=document.activeElement;trendReader.cancel();await nextTick();if(owner===scopeKey.value&&permitted.value&&(document.activeElement===active||document.activeElement===document.body))root.value?.focus()}
async function cancelRecords(){if(!records.value.busy)return;const owner=scopeKey.value,active=document.activeElement;recordReader.cancel();await nextTick();if(owner===scopeKey.value&&permitted.value&&(document.activeElement===active||document.activeElement===document.body))recordRegion.value?.focus()}
defineExpose({refresh})
const buckets=computed(()=>trend.value.current?.buckets??[]),peak=computed(()=>Math.max(1,...buckets.value.map(b=>b.raw_count))),x=(i:number)=>32+(i+.5)*608/Math.max(1,buckets.value.length),y=(n:number)=>166-n/peak.value*136
const points=(key:'raw_count'|'after_fingerprint_merge_count')=>buckets.value.map((b,i)=>`${x(i)},${y(b[key])}`).join(' ')
const labels={RAW_INTAKE:'原始记录',MERGE:'指纹归并',FLAP:'抖动静默',DEPENDENCY:'依赖抑制',MAINTENANCE:'维护静默',EFFECTIVE_ALERT:'有效告警记录（非最终通知）'}
const clock=(value:string)=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value))
function select(bucket:NoiseBucket){recordReader.reset(currentScope());void recordReader.load({from:bucket.from,to:bucket.to,cursor:null,pageSize:20})}
function selectIndex(value:string){const i=Number(value);if(value!==''&&Number.isInteger(i)&&i>=0&&i<buckets.value.length)select(buckets.value[i]!)}
function markerIndex(marker:NoiseMarker){const at=Date.parse(marker.recorded_at);return buckets.value.findIndex(b=>at>=Date.parse(b.from)&&at<Date.parse(b.to))}
function markerSelect(marker:NoiseMarker){const bucket=buckets.value[markerIndex(marker)];if(bucket)select(bucket)}
function next(){const current=records.value.current,q=records.value.query;if(current?.next&&q)void recordReader.load({...q,cursor:current.next})}
</script>
<template><div ref="root" class="noise-trend" role="group" tabindex="-1" aria-label="告警趋势读取区" :aria-busy="trend.busy"><p v-if="!permitted" role="status">当前账号无内部事件趋势权限。</p><template v-else>
<div class="trend-actions"><button :disabled="trend.busy" @click="refresh">刷新趋势</button><button v-if="trend.busy" @click="cancelTrend">取消趋势读取</button><button v-if="trend.current" :aria-expanded="showTable" @click="showTable=!showTable">{{showTable?'收起数值表':'查看数值表'}}</button></div><ApiErrorNotice :error="trend.error" :retrying="trend.busy" @retry="refresh"/><p v-if="trend.busy||trend.cancelled||trend.stale" role="status">{{trend.stale?'过期数据：保留上次同一范围的记录，未当作本次读取成功。':trend.busy?'正在读取完整时间桶…':'读取已取消，未沿用旧数据。'}}</p>
<template v-if="trend.current"><svg viewBox="0 0 672 204" role="img" aria-label="原始记录与指纹归并后记录趋势，数值表和各桶详情在下方可操作"><title>记录数趋势，不代表最终通知或采集健康</title><line x1="32" y1="166" x2="640" y2="166" class="axis"/><text x="2" y="32">{{peak}}</text><text x="12" y="166">0</text><polyline :points="points('raw_count')" class="raw-line"/><polyline :points="points('after_fingerprint_merge_count')" class="merged-line"/><circle v-for="(bucket,index) in buckets" :key="bucket.from" :cx="x(index)" :cy="y(bucket.raw_count)" r="3" class="raw-point"><title>{{clock(bucket.from)}}：原始 {{bucket.raw_count}}，指纹归并后 {{bucket.after_fingerprint_merge_count}}</title></circle><g v-for="marker in trend.current.markers" :key="marker.record_id"><circle :cx="x(markerIndex(marker))" cy="14" r="4" class="marker"><title>{{marker.rule_name}} · 记录时间 {{clock(marker.recorded_at)}}</title></circle></g><text x="32" y="194">{{clock(trend.current.period.from)}}</text><text x="640" y="194" text-anchor="end">{{clock(trend.current.period.to)}}</text></svg>
<p class="trend-note">本租户降噪日志原始记录的双序列；指纹归并后 = 原始 − 指纹归并记录。最终通知数尚未接入，降噪率未知。读取 {{displayTime(trend.current.observed_at)}}，不证明采集时效。</p>
<label>查看时间桶原始记录 <select aria-label="趋势原始记录时间桶" value="" @change="selectIndex(($event.target as HTMLSelectElement).value)"><option value="" disabled>选择时间桶</option><option v-for="(bucket,index) in buckets" :key="bucket.from" :value="index">{{clock(bucket.from)}} 至 {{clock(bucket.to)}} · 原始 {{bucket.raw_count}}</option></select></label>
<details v-if="trend.current.markers.length"><summary>近24小时事件标记 {{trend.current.markers.length}} 条{{trend.current.markers_truncated?'（仅最近8条）':''}}</summary><ul><li v-for="marker in trend.current.markers" :key="marker.record_id"><button @click="markerSelect(marker)">{{marker.rule_name}} · {{clock(marker.recorded_at)}}</button><router-link :to="{path:'/monitoring-events',query:{event_id:marker.event_id}}">事件详情</router-link></li></ul><small>时间为日志记录时间；名称和级别取当前事件资料，不冒充历史冻结快照。</small></details>
<details><summary>查看降噪各层记录</summary><dl><template v-for="layer in noiseLayers" :key="layer"><dt>{{labels[layer]}}</dt><dd>{{trend.current.totals[layer]}}</dd></template></dl><small>各层可能重叠，不将它们相加或全部相减伪造最终通知数。</small></details>
<div v-if="showTable" class="noise-table" role="region" tabindex="0" aria-label="趋势数值表，可横向滚动"><table><thead><tr><th scope="col">时间桶</th><th scope="col">原始</th><th scope="col">指纹归并后</th><th scope="col">明细</th></tr></thead><tbody><tr v-for="bucket in buckets" :key="bucket.from"><th scope="row">{{clock(bucket.from)}}</th><td>{{bucket.raw_count}}</td><td>{{bucket.after_fingerprint_merge_count}}</td><td><button @click="select(bucket)">查看原始记录</button></td></tr></tbody></table></div>
</template>
<section v-if="records.query" ref="recordRegion" tabindex="-1" aria-label="选定时间桶原始记录" :aria-busy="records.busy"><h3>原始记录：{{clock(records.query.from)}} 至 {{clock(records.query.to)}}</h3><div class="trend-actions"><button :disabled="records.busy" @click="recordReader.retry">重读原页</button><button v-if="records.busy" @click="cancelRecords">取消明细读取</button><button v-if="records.current?.next" :disabled="records.busy" @click="next">下一页原始记录</button></div><ApiErrorNotice :error="records.error"/><p v-if="records.busy||records.cancelled" role="status">{{records.busy?'正在读取原始记录…':'明细读取已取消，未沿用旧结果。'}}</p><template v-if="records.current"><p role="status">当前页 {{records.current.items.length}} 条 / 该时间桶共 {{records.current.total_count}} 条；明细单独重新授权读取，不是跨页冻结快照。</p><ul class="raw-records"><li v-for="row in records.current.items" :key="row.record_id"><time :datetime="row.recorded_at">{{displayTime(row.recorded_at)}}</time> {{row.detail}} <router-link :to="{path:'/monitoring-events',query:{event_id:row.event_id}}">查看事件原始成员</router-link></li></ul></template></section>
</template></div></template>
<style scoped>.noise-trend{min-width:0}.noise-trend svg{display:block;width:100%;max-height:220px}.axis{stroke:var(--mop-line,#d4dce8)}.raw-line,.merged-line{fill:none;stroke-width:2}.raw-line{stroke:#8993a1}.merged-line{stroke:var(--mop-primary,#2165c5)}.raw-point{fill:#8993a1}.marker{fill:var(--mop-primary,#2165c5)}svg text{font-size:11px;fill:var(--mop-muted,#5d6e83)}.trend-actions{display:flex;gap:8px;flex-wrap:wrap}.trend-note,small{color:var(--mop-muted,#5d6e83);font-size:12px}select{max-width:100%;min-height:28px}.noise-table{overflow:auto;max-width:100%}table{width:100%;min-width:420px;text-align:left;border-collapse:collapse}th,td{padding:6px;border-bottom:1px solid var(--mop-line,#d4dce8)}details{margin-top:8px}summary{cursor:pointer;min-height:28px}dl{display:grid;grid-template-columns:1fr auto;gap:6px}dd{margin:0}.raw-records{padding-left:18px;max-height:280px;overflow:auto;overflow-wrap:anywhere}.raw-records li{margin:8px 0}button{min-height:28px}h3{font-size:14px}</style>
